### 1. `Shared/ReadingSessionShared.swift` (добавить в приложение и в расширение DeviceActivityMonitor)

```swift
import DeviceActivity
import Foundation
import ManagedSettings

nonisolated enum SlumpyAppGroup {
    /// Must match the App Group enabled for the app and both extensions.
    static let identifier = "group.com.slumpy.app"
}

nonisolated extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("slumpy.readingSession") }
}

nonisolated struct ReadingSession: Codable, Sendable, Equatable {
    static let activityPrefix = "slumpy.reading."

    let id: UUID
    let startDate: Date
    let endDate: Date
    let plannedMinutes: Int
    /// Gregorian local day the session started on, "yyyy-MM-dd". Its minutes count toward this day.
    let dayKey: String

    static func starting(at start: Date, minutes: Int) -> ReadingSession {
        ReadingSession(
            id: UUID(),
            startDate: start,
            endDate: start.addingTimeInterval(TimeInterval(minutes * 60)),
            plannedMinutes: minutes,
            dayKey: dayKey(for: start)
        )
    }

    static func dayKey(for date: Date, timeZone: TimeZone = .current) -> String {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = timeZone
        let parts = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
    }

    /// Each session is monitored under its own name, so the extension knows exactly which session ended.
    var activityName: DeviceActivityName {
        DeviceActivityName(Self.activityPrefix + id.uuidString)
    }

    static func sessionID(from name: DeviceActivityName) -> UUID? {
        guard name.rawValue.hasPrefix(activityPrefix) else { return nil }
        return UUID(uuidString: String(name.rawValue.dropFirst(activityPrefix.count)))
    }
}

nonisolated struct CompletedReading: Codable, Sendable, Equatable {
    let sessionID: UUID
    let dayKey: String
    let minutes: Int
    let completedAt: Date
}

nonisolated struct ReadingState: Codable, Sendable, Equatable {
    var active: ReadingSession?
    var completed: [CompletedReading] = []
    /// Set when a session ends; cleared once Slumpy has said it.
    var pendingEndAnnouncement: UUID?

    private nonisolated enum CodingKeys: String, CodingKey {
        case active, completed, pendingEndAnnouncement
    }

    init() {}

    // Tolerant decoding so fields added later do not wipe existing history.
    init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        active = try container.decodeIfPresent(ReadingSession.self, forKey: .active)
        completed = try container.decodeIfPresent([CompletedReading].self, forKey: .completed) ?? []
        pendingEndAnnouncement = try container.decodeIfPresent(UUID.self, forKey: .pendingEndAnnouncement)
    }

    mutating func begin(_ session: ReadingSession) {
        active = session
        pendingEndAnnouncement = nil
    }

    mutating func discardActive(id: UUID) {
        if active?.id == id { active = nil }
    }

    /// Idempotent: the app and the extension may both call it for the same session.
    @discardableResult
    mutating func complete(sessionID: UUID, at date: Date) -> Bool {
        guard let session = active, session.id == sessionID else { return false }
        active = nil
        if !completed.contains(where: { $0.sessionID == session.id }) {
            completed.append(CompletedReading(
                sessionID: session.id,
                dayKey: session.dayKey,
                minutes: session.plannedMinutes,
                completedAt: date
            ))
        }
        pendingEndAnnouncement = session.id
        return true
    }

    @discardableResult
    mutating func completeActiveIfExpired(at date: Date) -> Bool {
        guard let session = active, date >= session.endDate else { return false }
        return complete(sessionID: session.id, at: date)
    }

    func minutes(onDayKey dayKey: String) -> Int {
        completed.filter { $0.dayKey == dayKey }.reduce(0) { $0 + $1.minutes }
    }
}

/// Shared state of reading sessions in the App Group container.
/// The app and the monitor extension are separate processes, so every change is a coordinated
/// read-modify-write of one small JSON file.
nonisolated struct ReadingStateStore: Sendable {
    private let fileURL: URL

    init?(appGroup: String = SlumpyAppGroup.identifier) {
        guard let container = FileManager.default.containerURL(
            forSecurityApplicationGroupIdentifier: appGroup
        ) else { return nil }
        fileURL = container.appending(path: "reading-state.json")
    }

    init(fileURL: URL) {
        self.fileURL = fileURL
    }

    /// nil when the file exists but cannot be read, e.g. the phone has not been unlocked since reboot.
    func read() -> ReadingState? {
        var state: ReadingState?
        var coordinationError: NSError?
        NSFileCoordinator().coordinate(readingItemAt: fileURL, options: [], error: &coordinationError) { url in
            state = try? Self.load(from: url)
        }
        return state
    }

    /// Returns nil and writes nothing when the file is unavailable or the write fails.
    @discardableResult
    func update<T>(_ change: (inout ReadingState) -> T) -> T? {
        var result: T?
        var coordinationError: NSError?
        NSFileCoordinator().coordinate(writingItemAt: fileURL, options: [], error: &coordinationError) { url in
            guard var state = try? Self.load(from: url) else { return }
            let original = state
            let value = change(&state)
            if state != original {
                guard (try? Self.save(state, to: url)) != nil else { return }
            }
            result = value
        }
        return result
    }

    private static func load(from url: URL) throws -> ReadingState {
        guard FileManager.default.fileExists(atPath: url.path(percentEncoded: false)) else {
            return ReadingState()
        }
        let data = try Data(contentsOf: url)
        do {
            return try JSONDecoder().decode(ReadingState.self, from: data)
        } catch {
            // Keep the damaged file for diagnosis instead of silently overwriting reading history.
            let name = url.deletingPathExtension().lastPathComponent
            let backup = url.deletingLastPathComponent()
                .appending(path: "\(name).corrupt-\(Int(Date.now.timeIntervalSince1970)).json")
            try? FileManager.default.moveItem(at: url, to: backup)
            return ReadingState()
        }
    }

    private static func save(_ state: ReadingState, to url: URL) throws {
        let data = try JSONEncoder().encode(state)
        // Readable while the phone is locked: the monitor extension runs at session end regardless.
        try data.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }
}
```

