### 3. `App/ReadingSessionController.swift` (приложение)

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation

enum ReadingSessionError: Error {
    case alreadyRunning
    case durationTooShort
    case storageUnavailable
}

@Observable
final class ReadingSessionController {
    /// DeviceActivity rejects schedules shorter than 15 minutes.
    static let minimumMinutes = 15

    private(set) var activeSession: ReadingSession?
    /// What Slumpy should say now; nil when there is nothing to announce.
    private(set) var slumpyLine: String?
    /// Minutes credited to today's goal.
    private(set) var todayMinutes = 0

    @ObservationIgnored private let store: ReadingStateStore
    @ObservationIgnored private let shields = ManagedSettingsStore(named: .readingSession)
    @ObservationIgnored private let center = DeviceActivityCenter()
    @ObservationIgnored private var endCheck: Task<Void, Never>?

    init() {
        guard let store = ReadingStateStore() else {
            preconditionFailure("App Group \(SlumpyAppGroup.identifier) is not configured")
        }
        self.store = store
    }

    func start(minutes: Int = 30, blocking selection: FamilyActivitySelection) async throws {
        await reconcile()
        guard activeSession == nil else { throw ReadingSessionError.alreadyRunning }
        guard minutes >= Self.minimumMinutes else { throw ReadingSessionError.durationTooShort }

        let session = ReadingSession.starting(at: .now, minutes: minutes)
        // State first, so the extension always finds the session it is asked to end.
        guard store.update({ $0.begin(session) }) != nil else {
            throw ReadingSessionError.storageUnavailable
        }
        do {
            try center.startMonitoring(session.activityName, during: Self.schedule(for: session))
        } catch {
            store.update { $0.discardActive(id: session.id) }
            throw error
        }
        applyShields(selection)
        startLiveActivity(for: session)
        activeSession = session
        slumpyLine = nil
        scheduleEndCheck(at: session.endDate)
    }

    /// Brings the app in line with the shared state. Safe to call any number of times:
    /// on launch, on every return to the foreground, and when the session time runs out.
    func reconcile() async {
        endCheck?.cancel()
        endCheck = nil
        let now = Date.now
        let updated = store.update { (state: inout ReadingState) -> ReadingState in
            // Fallback for when the extension did not run: finish an expired session here.
            state.completeActiveIfExpired(at: now)
            let snapshot = state
            state.pendingEndAnnouncement = nil
            return snapshot
        }
        guard let state = updated ?? store.read() else {
            // Shared state is unreadable: fail open so apps never stay blocked.
            activeSession = nil
            shields.clearAllSettings()
            stopSessionMonitoring(except: nil)
            await endLiveActivities()
            return
        }

        // Everything the UI shows is set before any suspension point.
        let running = state.active.flatMap { $0.endDate > now ? $0 : nil }
        activeSession = running
        todayMinutes = state.minutes(onDayKey: ReadingSession.dayKey(for: now))
        if state.pendingEndAnnouncement != nil || (state.active != nil && running == nil) {
            slumpyLine = String(localized: "Сессия окончена")
        }

        if let running {
            stopSessionMonitoring(except: running)
            scheduleEndCheck(at: running.endDate)
        } else {
            shields.clearAllSettings()
            stopSessionMonitoring(except: nil)
            await endLiveActivities()
        }
    }

    func dismissSlumpyLine() {
        slumpyLine = nil
    }

    // MARK: - Private

    private static func schedule(for session: ReadingSession) -> DeviceActivitySchedule {
        let calendar = Calendar.current
        let parts: Set<Calendar.Component> = [.year, .month, .day, .hour, .minute, .second]
        return DeviceActivitySchedule(
            intervalStart: calendar.dateComponents(parts, from: session.startDate),
            intervalEnd: calendar.dateComponents(parts, from: session.endDate),
            repeats: false
        )
    }

    private func stopSessionMonitoring(except session: ReadingSession?) {
        let stale = center.activities.filter {
            ReadingSession.sessionID(from: $0) != nil && $0 != session?.activityName
        }
        if !stale.isEmpty { center.stopMonitoring(stale) }
    }

    private func applyShields(_ selection: FamilyActivitySelection) {
        let apps = selection.applicationTokens
        let categories = selection.categoryTokens
        let domains = selection.webDomainTokens
        shields.shield.applications = apps.isEmpty ? nil : apps
        shields.shield.applicationCategories = categories.isEmpty ? nil : .specific(categories)
        shields.shield.webDomains = domains.isEmpty ? nil : domains
        shields.shield.webDomainCategories = categories.isEmpty ? nil : .specific(categories)
    }

    private func startLiveActivity(for session: ReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let attributes = ReadingSessionAttributes(startDate: session.startDate, endDate: session.endDate)
        // staleDate lets the widget switch to "finished" on its own while the app is not running.
        let content = ActivityContent(
            state: ReadingSessionAttributes.ContentState(isFinished: false),
            staleDate: session.endDate
        )
        // The Live Activity is a convenience; the session runs without it.
        _ = try? Activity.request(attributes: attributes, content: content, pushType: nil)
    }

    private func endLiveActivities() async {
        let final = ActivityContent(state: ReadingSessionAttributes.ContentState(isFinished: true), staleDate: nil)
        for activity in Activity<ReadingSessionAttributes>.activities {
            await activity.end(final, dismissalPolicy: .immediate)
        }
    }

    private func scheduleEndCheck(at endDate: Date) {
        endCheck?.cancel()
        endCheck = Task { [weak self] in
            // One extra second so the check never lands just before endDate.
            try? await Task.sleep(for: .seconds(max(0, endDate.timeIntervalSinceNow) + 1))
            guard !Task.isCancelled, let self else { return }
            self.endCheck = nil
            await self.reconcile()
        }
    }
}
