import SwiftUI

/// Attach once to the root view. In the App struct:
/// `@State private var readingSessions = ReadingSessionController()`
/// `RootView().environment(readingSessions).modifier(ReadingSessionLifecycle())`
struct ReadingSessionLifecycle: ViewModifier {
    @Environment(ReadingSessionController.self) private var sessions
    @Environment(\.scenePhase) private var scenePhase

    func body(content: Content) -> some View {
        content
            .onChange(of: scenePhase, initial: true) { _, phase in
                guard phase == .active else { return }
                Task { await sessions.reconcile() }
            }
            .overlay(alignment: .bottom) {
                if let line = sessions.slumpyLine {
