### 5. `Monitor/SlumpyDeviceActivityMonitor.swift` (расширение DeviceActivityMonitor, основной класс расширения)

```swift
import DeviceActivity
import Foundation
import ManagedSettings

// Nonisolated: the system calls these overrides off the main actor and the superclass
// declarations are nonisolated, so a main-actor override would not match them.
nonisolated final class SlumpyDeviceActivityMonitor: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        guard let sessionID = ReadingSession.sessionID(from: activity) else { return }
        let store = ReadingStateStore()

        // A late callback for an older session must not end the session running now.
        if let active = store?.read()?.active, active.id != sessionID {
            return
        }
        // Unblock first: it does not depend on the shared file being readable.
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
        store?.update { $0.complete(sessionID: sessionID, at: .now) }
    }
}
```

