/// Stale means the end time has passed even if the app could not update the activity.
private func isFinished(_ context: ActivityViewContext<ReadingSessionAttributes>) -> Bool {
    context.state.isFinished || context.isStale
}

private struct ReadingSessionLockScreenView: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        HStack(spacing: 12) {
            Image(systemName: isFinished(context) ? "checkmark.circle.fill" : "book.fill")
                .font(.title2)
            ReadingStatus(context: context)
            Spacer(minLength: 0)
            ReadingTimerText(context: context)
                .font(.title2.monospacedDigit())
        }
        .padding()
    }
}

