import DeviceActivity
import Foundation
import Testing
@testable import Slumpy

struct ReadingStateTests {
    // 2027-01-15 08:00:00 UTC
    let start = Date(timeIntervalSince1970: 1_800_000_000)

    @Test func doesNotCompleteBeforeEnd() {
        var state = ReadingState()
        let session = ReadingSession.starting(at: start, minutes: 30)
        state.begin(session)
        #expect(state.completeActiveIfExpired(at: session.endDate.addingTimeInterval(-1)) == false)
        #expect(state.active == session)
        #expect(state.completed.isEmpty)
    }

    @Test func completesAtEndAndCreditsPlannedMinutes() {
        var state = ReadingState()
        let session = ReadingSession.starting(at: start, minutes: 30)
        state.begin(session)
        #expect(state.completeActiveIfExpired(at: session.endDate))
        #expect(state.active == nil)
        #expect(state.completed.map(\.minutes) == [30])
        #expect(state.pendingEndAnnouncement == session.id)
    }

    @Test func completingTwiceCreditsOnce() {
        var state = ReadingState()
        let session = ReadingSession.starting(at: start, minutes: 30)
        state.begin(session)
        state.complete(sessionID: session.id, at: session.endDate)
        state.active = session
        state.complete(sessionID: session.id, at: session.endDate)
        #expect(state.completed.count == 1)
    }

    @Test func ignoresCallbackForAnotherSession() {
        var state = ReadingState()
        let session = ReadingSession.starting(at: start, minutes: 30)
        state.begin(session)
        #expect(state.complete(sessionID: UUID(), at: session.endDate) == false)
        #expect(state.active == session)
    }

    @Test func sumsMinutesPerDay() {
        var state = ReadingState()
        for minutes in [30, 20] {
            let session = ReadingSession.starting(at: start, minutes: minutes)
            state.begin(session)
            state.complete(sessionID: session.id, at: session.endDate)
        }
        let key = ReadingSession.dayKey(for: start)
        #expect(state.minutes(onDayKey: key) == 50)
        #expect(state.minutes(onDayKey: "1999-01-01") == 0)
    }

    @Test func beginningClearsOldAnnouncement() {
        var state = ReadingState()
        state.pendingEndAnnouncement = UUID()
        state.begin(ReadingSession.starting(at: start, minutes: 30))
        #expect(state.pendingEndAnnouncement == nil)
    }

    @Test func decodesFileWithoutNewerFields() throws {
        let state = try JSONDecoder().decode(ReadingState.self, from: Data("{}".utf8))
        #expect(state == ReadingState())
    }

    @Test func dayKeyIsGregorianInGivenTimeZone() throws {
        let utc = try #require(TimeZone(secondsFromGMT: 0))
        let alaska = try #require(TimeZone(secondsFromGMT: -9 * 3600))
        #expect(ReadingSession.dayKey(for: start, timeZone: utc) == "2027-01-15")
        #expect(ReadingSession.dayKey(for: start, timeZone: alaska) == "2027-01-14")
    }

    @Test func sessionIDRoundTripsThroughActivityName() {
        let session = ReadingSession.starting(at: start, minutes: 30)
        #expect(ReadingSession.sessionID(from: session.activityName) == session.id)
        #expect(ReadingSession.sessionID(from: DeviceActivityName("other")) == nil)
    }
}

