```swift
import DeviceActivity
import Foundation
import ManagedSettings

nonisolated enum AppGroup {
    /// ASSUMPTION: replace with the App Group ID already configured in the project.
    static let identifier = "group.app.slumpy"

    static func defaults() -> UserDefaults {
        // UserDefaults(suiteName:) succeeds even without the entitlement, silently using a
        // private store, so check the container to catch a misconfigured target in debug builds.
        assert(
            FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: identifier) != nil,
            "App Group \(identifier) is missing from this target's entitlements"
        )
        return UserDefaults(suiteName: identifier) ?? .standard
    }
}

/// The running reading session. Its end date is the single source of truth for "time is up".
nonisolated struct ActiveReadingSession: Codable, Equatable, Sendable {
    let id: UUID
    let startDate: Date
    let endDate: Date

    var minutes: Int { Int((endDate.timeIntervalSince(startDate) / 60).rounded()) }
}

/// A finished session that Slumpy has not announced yet.
nonisolated struct SessionAnnouncement: Codable, Equatable, Sendable {
    let sessionID: UUID
    let minutes: Int
}

/// Reading-session state in the App Group. Only the app writes it; the monitor extension reads it.
nonisolated struct SharedSessionStore {
    private static let activeSessionKey = "readingSession.active.v1"
    private static let announcementKey = "readingSession.announcement.v1"

    private let defaults = AppGroup.defaults()

    var activeSession: ActiveReadingSession? {
        get { read(Self.activeSessionKey) }
        nonmutating set { write(newValue, Self.activeSessionKey) }
    }

    var announcement: SessionAnnouncement? {
        get { read(Self.announcementKey) }
        nonmutating set { write(newValue, Self.announcementKey) }
    }

    private func read<Value: Decodable>(_ key: String) -> Value? {
        guard let data = defaults.data(forKey: key) else { return nil }
        return try? JSONDecoder().decode(Value.self, from: data)
    }

    private func write<Value: Encodable>(_ value: Value?, _ key: String) {
        if let value {
            defaults.set(try? JSONEncoder().encode(value), forKey: key)
        } else {
            defaults.removeObject(forKey: key)
        }
    }
}

/// Holds only reading-session shields, so clearing it never touches other features.
nonisolated extension ManagedSettingsStore.Name {
    static var readingSession: Self { Self("slumpy.readingSession") }
}

/// The session id is part of the activity name, so a schedule left over from an earlier
/// session can be told apart from the current one.
nonisolated enum ReadingSessionActivity {
    private static let prefix = "slumpy.readingSession."

    static func name(for sessionID: UUID) -> DeviceActivityName {
        DeviceActivityName(prefix + sessionID.uuidString)
    }

    static func sessionID(from name: DeviceActivityName) -> UUID? {
        guard name.rawValue.hasPrefix(prefix) else { return nil }
        return UUID(uuidString: String(name.rawValue.dropFirst(prefix.count)))
    }
}

nonisolated enum ReadingSessionRules {
    /// DeviceActivity rejects intervals shorter than this.
    static let minimumMonitoringInterval: TimeInterval = 15 * 60

    /// Only the end of the interval matters, so a short session moves the start into the past.
    static func monitoringInterval(for session: ActiveReadingSession) -> (start: Date, end: Date) {
        (min(session.startDate, session.endDate - minimumMonitoringInterval), session.endDate)
    }

    static func isDue(_ session: ActiveReadingSession, now: Date) -> Bool {
        now >= session.endDate
    }

    /// No readable session means no reading shields should exist, so clearing is the safe default.
    /// Only a newer session's shields are kept.
    static func shouldClearShields(endingActivity name: DeviceActivityName, active: ActiveReadingSession?) -> Bool {
        guard let endedSessionID = ReadingSessionActivity.sessionID(from: name) else { return false }
        guard let active else { return true }
        return active.id == endedSessionID
    }
}
