```swift
import Foundation

/// Minutes read per calendar day, toward the daily goal. Only the app writes it, on the main actor.
struct DailyReadingLedger {
    nonisolated private struct Storage: Codable {
        var minutesByDay: [String: Int] = [:]
        var creditedSessionIDs: [UUID] = []
    }

    private static let storageKey = "readingLedger.v1"
    /// Far more than the sessions that can wait to be credited at once.
    private static let creditedHistoryLimit = 100

    private let defaults: UserDefaults

    init(defaults: UserDefaults = AppGroup.defaults()) {
        self.defaults = defaults
    }

    func minutes(on day: Date, calendar: Calendar = .current) -> Int {
        load().minutesByDay[Self.dayKey(day, calendar), default: 0]
    }

    /// Idempotent: crediting the same session again has no effect.
    func credit(minutes: Int, forSession sessionID: UUID, on day: Date, calendar: Calendar = .current) {
        var storage = load()
        guard minutes > 0, !storage.creditedSessionIDs.contains(sessionID) else { return }
        storage.minutesByDay[Self.dayKey(day, calendar), default: 0] += minutes
        storage.creditedSessionIDs.append(sessionID)
        storage.creditedSessionIDs = Array(storage.creditedSessionIDs.suffix(Self.creditedHistoryLimit))
        defaults.set(try? JSONEncoder().encode(storage), forKey: Self.storageKey)
    }

    private func load() -> Storage {
        guard let data = defaults.data(forKey: Self.storageKey) else { return Storage() }
        return (try? JSONDecoder().decode(Storage.self, from: data)) ?? Storage()
    }

    private static func dayKey(_ date: Date, _ calendar: Calendar) -> String {
        let parts = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d", parts.year ?? 0, parts.month ?? 0, parts.day ?? 0)
    }
}
