### 4. `App/ReadingSessionController.swift`

```swift
import ActivityKit
import DeviceActivity
import FamilyControls
import Foundation
import ManagedSettings
import Observation
import os

private let logger = Logger(subsystem: "app.slumpy", category: "ReadingSession")

@Observable
final class ReadingSessionController {
    enum StartError: Error {
        case alreadyRunning
        case monitoringFailed(any Error)
    }

    private(set) var activeSession: ActiveReadingSession?
    /// Non-nil while Slumpy still has to say "Сессия окончена".
    private(set) var announcement: SessionAnnouncement?
    private(set) var todayMinutes = 0

    @ObservationIgnored private let store = SharedSessionStore()
    @ObservationIgnored private let ledger = DailyReadingLedger()
    @ObservationIgnored private var foregroundTimer: Task<Void, Never>?

    init() {
        refreshFromStore()
    }

    /// Synchronous on purpose: no other call can interleave between the checks and the writes.
    func start(minutes: Int, blocking selection: FamilyActivitySelection?) throws {
        if let current = store.activeSession {
            guard ReadingSessionRules.isDue(current, now: .now) else { throw StartError.alreadyRunning }
            finish(current)
        }
        acknowledgeAnnouncement()

        let now = Date.now
        let session = ActiveReadingSession(id: UUID(), startDate: now, endDate: now + TimeInterval(minutes * 60))
        // Persisted before the schedule exists, so the extension always recognises its session.
        store.activeSession = session
        if let selection { applyShields(selection) }
        do {
            try startMonitoring(session)
        } catch {
            // Without a schedule nothing would lift the shields in the background.
            clearShields()
            store.activeSession = nil
            throw StartError.monitoringFailed(error)
        }
        activeSession = session
        startLiveActivity(for: session)
        scheduleForegroundFinish(for: session)
    }

    /// Call on launch and whenever the scene becomes active.
    func reconcile() {
        if let session = store.activeSession {
            if ReadingSessionRules.isDue(session, now: .now) {
                finish(session)
            } else {
                ensureMonitoring(session)
                scheduleForegroundFinish(for: session)
            }
        } else {
            // No session means no reading shields, whatever left them behind.
            clearShields()
            stopReadingActivities()
        }
        refreshFromStore()
        Task { await Self.endInactiveLiveActivities() }
    }

    func acknowledgeAnnouncement() {
        store.announcement = nil
        announcement = nil
    }

    /// Idempotent and fully synchronous; a crash at any step is repaired by the next reconcile.
    private func finish(_ session: ActiveReadingSession) {
        guard store.activeSession?.id == session.id else { return }
        clearShields()
        stopReadingActivities()
        ledger.credit(minutes: session.minutes, forSession: session.id, on: session.startDate)
        store.announcement = SessionAnnouncement(sessionID: session.id, minutes: session.minutes)
        store.activeSession = nil
        foregroundTimer?.cancel()
        refreshFromStore()
        Task { await Self.endInactiveLiveActivities() }
    }

    private func refreshFromStore() {
        activeSession = store.activeSession
        announcement = store.announcement
        todayMinutes = ledger.minutes(on: .now)
    }

    // MARK: Shields and schedule

    private func applyShields(_ selection: FamilyActivitySelection) {
        let shieldStore = ManagedSettingsStore(named: .readingSession)
        shieldStore.shield.applications = selection.applicationTokens.isEmpty ? nil : selection.applicationTokens
        shieldStore.shield.webDomains = selection.webDomainTokens.isEmpty ? nil : selection.webDomainTokens
        if selection.categoryTokens.isEmpty {
            shieldStore.shield.applicationCategories = nil
            shieldStore.shield.webDomainCategories = nil
        } else {
            shieldStore.shield.applicationCategories = .specific(selection.categoryTokens)
            shieldStore.shield.webDomainCategories = .specific(selection.categoryTokens)
        }
    }

    private func clearShields() {
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }

    private func startMonitoring(_ session: ActiveReadingSession) throws {
        stopReadingActivities()
        let interval = ReadingSessionRules.monitoringInterval(for: session)
        let schedule = DeviceActivitySchedule(
            intervalStart: Self.components(interval.start),
            intervalEnd: Self.components(interval.end),
            repeats: false
        )
        try DeviceActivityCenter().startMonitoring(ReadingSessionActivity.name(for: session.id), during: schedule)
    }

    /// Re-registers the schedule if it went missing, so the background unblock still happens.
    private func ensureMonitoring(_ session: ActiveReadingSession) {
        let name = ReadingSessionActivity.name(for: session.id)
        guard !DeviceActivityCenter().activities.contains(name) else { return }
        do {
            try startMonitoring(session)
        } catch {
            logger.error("Reading schedule not restored: \(error.localizedDescription)")
        }
    }

    private func stopReadingActivities() {
        let center = DeviceActivityCenter()
        let readingActivities = center.activities.filter { ReadingSessionActivity.sessionID(from: $0) != nil }
        // stopMonitoring([]) would stop every activity of the app, not none.
        if !readingActivities.isEmpty { center.stopMonitoring(readingActivities) }
    }

    private static func components(_ date: Date) -> DateComponents {
        Calendar.current.dateComponents([.year, .month, .day, .hour, .minute, .second], from: date)
    }

    // MARK: Live Activity

    private func startLiveActivity(for session: ActiveReadingSession) {
        guard ActivityAuthorizationInfo().areActivitiesEnabled else { return }
        let state = ReadingSessionAttributes.ContentState(
            startDate: session.startDate, endDate: session.endDate, isFinished: false
        )
        do {
            // staleDate lets the widget show the finished state while the app is not running.
            _ = try Activity.request(
                attributes: ReadingSessionAttributes(sessionID: session.id),
                content: ActivityContent(state: state, staleDate: session.endDate),
                pushType: nil
            )
        } catch {
            logger.error("Live Activity not started: \(error.localizedDescription)")
        }
    }

    /// Ends every Live Activity except the running session's. Activities are listed before the
    /// active id is read: `start` persists the session before requesting its activity, so a
    /// session started meanwhile is either not listed yet or already recognised as active.
    nonisolated private static func endInactiveLiveActivities() async {
        let activities = Activity<ReadingSessionAttributes>.activities
        let activeID = SharedSessionStore().activeSession?.id
        for activity in activities where activity.attributes.sessionID != activeID {
            var state = activity.content.state
            state.isFinished = true
            await activity.end(ActivityContent(state: state, staleDate: nil), dismissalPolicy: .immediate)
        }
    }

    // MARK: Foreground timer

    private func scheduleForegroundFinish(for session: ActiveReadingSession) {
        foregroundTimer?.cancel()
        foregroundTimer = Task { [weak self] in
            try? await Task.sleep(for: .seconds(max(0, session.endDate.timeIntervalSinceNow)))
            guard !Task.isCancelled else { return }
            self?.finish(session)
        }
    }
}
