import DeviceActivity
import ManagedSettings

/// Lifts reading-session shields when the session's interval ends, even if the app is suspended
/// or terminated. The app credits minutes and ends the Live Activity on its next launch.
nonisolated final class ReadingSessionMonitor: DeviceActivityMonitor {
    override func intervalDidEnd(for activity: DeviceActivityName) {
        super.intervalDidEnd(for: activity)
        let active = SharedSessionStore().activeSession
        guard ReadingSessionRules.shouldClearShields(endingActivity: activity, active: active) else { return }
        ManagedSettingsStore(named: .readingSession).clearAllSettings()
    }
}
